  `tabela_afetada` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'Nome da tabela na qual houve interação',
  `id_registro` int NOT NULL COMMENT 'Identificação do registro que foi modificado',
