  `valor_antigo` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT 'Informação anterior a alteração',
  `valor_novo` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT 'Informação posterior a alteração',
  `data_evento` datetime DEFAULT (now()) COMMENT 'Horário da interação com o registro',
  PRIMARY KEY (`id_log`),
  KEY `fk_log_usuario` (`id_usuario`),
  CONSTRAINT `fk_log_usuario` FOREIGN KEY (`id_usuario`) REFERENCES `usuarios` (`id_usuario`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='Registro de todas as interações com dados do sistema.';

